<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\MaintenanceRequest; use App\Models\Property; use App\Models\PropertySpace; use App\Services\AuditService; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class MaintenanceController extends Controller { public function index(Request $r):JsonResponse{return $this->success(['items'=>MaintenanceRequest::where('organization_id',$r->attributes->get('organization_id'))->when($r->filled('propertyId'),fn($q)=>$q->where('property_id',$r->string('propertyId')))->orderByDesc('created_at')->get()->map(fn($m)=>$this->data($m))]);} public function show(Request $r,string $id):JsonResponse{return $this->success($this->data($this->find($r,$id)));} public function store(Request $r):JsonResponse{$d=$r->validate(['propertyId'=>['required','uuid'],'spaceId'=>['nullable','uuid'],'ownerId'=>['nullable','uuid'],'title'=>['required','string','max:255'],'description'=>['nullable','string','max:5000'],'priority'=>['required','in:low,medium,high,urgent'],'estimatedCost'=>['required','numeric','gte:0'],'requiresOwnerApproval'=>['boolean']]);$org=$r->attributes->get('organization_id');$m=DB::transaction(function()use($d,$org){$p=Property::where('organization_id',$org)->findOrFail($d['propertyId']);if(($d['spaceId']??null)&&!PropertySpace::where('organization_id',$org)->where('property_id',$p->id)->whereKey($d['spaceId'])->exists())abort(422,'المساحة لا تتبع العقار.');return MaintenanceRequest::create(['id'=>(string)Str::uuid(),'organization_id'=>$org,'property_id'=>$p->id,'space_id'=>$d['spaceId']??null,'owner_id'=>$d['ownerId']??null,'title'=>$d['title'],'description'=>$d['description']??null,'priority'=>$d['priority'],'estimated_cost'=>$d['estimatedCost'],'requires_owner_approval'=>$d['requiresOwnerApproval']??false,'approval_status'=>($d['requiresOwnerApproval']??false)?'pending':'not_required','status'=>($d['requiresOwnerApproval']??false)?'draft':'active']);});AuditService::record($org,$r->user()->id,'maintenance.created','maintenance_request',$m->id,null,$this->data($m));return $this->success($this->data($m),[],201);} public function decide(Request $r,string $id):JsonResponse{$d=$r->validate(['decision'=>['required','in:approved,rejected'],'reason'=>['nullable','string','max:1000']]);$org=$r->attributes->get('organization_id');$m=DB::transaction(function()use($r,$id,$d,$org){$m=$this->find($r,$id,true);if($m->approval_status!=='pending')abort(409,'طلب الصيانة ليس بانتظار الاعتماد.');$before=$this->data($m);$m->update(['approval_status'=>$d['decision'],'status'=>$d['decision']==='approved'?'active':'cancelled','version'=>$m->version+1]);DB::table('maintenance_approvals')->insert(['id'=>(string)Str::uuid(),'maintenance_request_id'=>$m->id,'decision'=>$d['decision'],'decided_by'=>$r->user()->id,'reason'=>$d['reason']??null,'decided_at'=>now()]);AuditService::record($org,$r->user()->id,'maintenance.'.$d['decision'],'maintenance_request',$m->id,$before,$this->data($m),$d['reason']??null);return $m;});return $this->success($this->data($m));} private function find(Request $r,string $id,bool $lock=false):MaintenanceRequest{$q=MaintenanceRequest::where('organization_id',$r->attributes->get('organization_id'));if($lock)$q->lockForUpdate();return $q->findOrFail($id);} private function data(MaintenanceRequest $m):array{return ['id'=>$m->id,'propertyId'=>$m->property_id,'spaceId'=>$m->space_id,'ownerId'=>$m->owner_id,'title'=>$m->title,'description'=>$m->description,'priority'=>$m->priority,'estimatedCost'=>(float)$m->estimated_cost,'actualCost'=>$m->actual_cost===null?null:(float)$m->actual_cost,'requiresOwnerApproval'=>$m->requires_owner_approval,'approvalStatus'=>$m->approval_status,'status'=>$m->status,'version'=>$m->version];}}
